        LDA     #$FF
        STA     $FF02           ; DDRB = $FF: every port B line an output
        LDA     #$04
        STA     $FF03           ; CRB bit 2: a $FF02 write now goes to ORB
        CLR     $FF02           ; ORB = 0, so a read of port B returns 0 in both emulators
